<script lang="ts">
 import type {Readable} from 'svelte/store';
 let {store,controller,overlays}=$props<{store:Readable<any>,controller:any,overlays:any}>();
 let root=$state<HTMLDivElement>();
 let open=$derived($store.open);
 $effect(()=>{if(open&&root)return overlays.enter(root,{escape:controller.close});});
</script>
{#if $store.open}<div class="cooking-repair-overlay" data-ui-owner="svelte" bind:this={root}><!-- Retain the original section/dialog markup and CSS. --><!-- svelte-ignore a11y_no_noninteractive_element_to_interactive_role --><section class="cr-window" role="dialog" tabindex="-1" aria-modal="true" aria-label="恢复设施"><header><h1>{$store.title}</h1><button data-action="close" aria-label="关闭恢复界面" onclick={controller.close}>×</button></header><div class="cr-body"><p class="cr-muted">{$store.clean?'✓ 清理场地　›　修补基础':'清理场地　›　修补基础'}</p><h2>{$store.ready?'基础设施已经恢复':$store.clean?'可以着手修补了':'清理荒废场地'}</h2><p>{$store.description}</p><p>当前体力：{$store.stamina}</p><p class="cr-muted">每 tick 基础劳动消耗 3 体力；当前劳动消耗 {$store.cost}。生存消耗照常结算，可随时暂停。</p><p role="status">{$store.message}</p><footer>{#if $store.ready}<button data-action="use" onclick={()=>controller.act('use')}>进入管理</button>{:else if $store.clean}<button data-action="repair" onclick={()=>controller.act('repair')}>准备修复材料</button>{:else}<button data-action={$store.running?'pause':'start'} disabled={!$store.running&&!!$store.reason} onclick={()=>controller.act($store.running?'pause':'start')}>{$store.running?'暂停清理':$store.started?'继续清理':'开始清理'}</button>{/if}<button data-action="close" onclick={controller.close}>{$store.running?'停下并离开':'离开'}</button></footer></div></section></div>{/if}
